import {createDayNight,bindDayNight} from './day-night.mjs';
import {resolveLocationView,LOCATION_WALKS} from './location-views.mjs';
import {bindTreeToggle} from './tree-layer.mjs';
import {CHURTON_VIEWS} from './churton-ward.mjs';
import {CHURCH_VIEWS} from './church-grounds.mjs';
import {UPTON_VIEWS} from './upton-frith-oscroft.mjs';
import {IRBY_ASHLEY_VIEWS} from './irby-ashley.mjs';
import {GRAFTON_EDGE_VIEWS} from './grafton-edge.mjs';
import {HALE_WARD_VIEWS} from './hale-daresbury-huxley-dunham.mjs';
import {ESTATES_VIEWS} from './estates-department.mjs';
import {FARNDON_VIEWS} from './farndon-ward.mjs';
import {FARNDON_CORRIDOR_WALK,WARD_CORRIDOR_WALK} from './farndon-corridor.mjs';
import {IRBY_CORRIDOR_WALK} from './irby-corridor.mjs';
import {WITBY_VIEWS} from './witby-ward.mjs';
import {GARAGE_MORTUARY_VIEWS} from './garages-mortuary.mjs';
import {GREENHOUSE_VIEWS} from './greenhouses.mjs';
import {OUTHOUSE_VIEWS} from './outhouse.mjs';
import {LAUNDRY_VIEWS} from './laundry.mjs';
import {MAIN_ADMIN_VIEWS} from './main-admin-building.mjs';
import {createAerialLayouts} from './aerial-layouts.mjs';
import {prepareEstateTimeline} from './estate-timeline.mjs';
import {bindTimelineControls} from './timeline-controls.mjs';
import {WATER_TOWER_VIEWS} from './water-tower.mjs';
import {TOWER_BUILDING_VIEWS} from './tower-buildings.mjs';
import {ANNEXE_VIEWS,ANNEXE_WARD_WALKS} from './annexe.mjs';
import * as THREE from './vendor/three.module.js';
import {createEscapeExterior,loadEscapeFrontage} from './escape-exterior.mjs';
import {FRONT_STEPS_VIEW} from './front-steps.mjs';
import {FRONT_WALL_VIEW} from './front-boundary-wall.mjs';
import {REDESMERE_PASSAGE_VIEW} from './redesmere-passage.mjs';
import {REDESMERE_CHIMNEY_VIEWS} from './redesmere-edge-chimney.mjs';
import {createWalker,exteriorObstacles} from './explore-controls.mjs';
import {bindExploreInput} from './explore-input.mjs';
import {EAST_PHOTO_VIEW} from './east-photo-detail.mjs';
import {COURTYARD_PHOTO_VIEW} from './courtyard-photo-detail.mjs';
import {REAR_COURT_PHOTO_VIEW} from './rear-court-photo-detail.mjs';
import {WEST_FRONT_PHOTO_VIEW} from './west-front-photo-detail.mjs';
import {WEST_COURT_PHOTO_VIEW} from './west-court-photo-detail.mjs';
import {centralCourtPhotoView} from './central-court-photo-detail.mjs';
import {innerEastPhotoView} from './inner-east-elevation.mjs';
import {WEST_WING_SIDE_VIEW,WEST_WING_END_VIEW} from './west-wing-photo-detail.mjs';
import {INNER_COURT_PHOTO_VIEW} from './inner-court-photo-detail.mjs';
import {REDESMERE_PHOTO_VIEW} from './redesmere-photo-detail.mjs';
import {EAST_LAWN_PHOTO_VIEW,ENTRANCE_EAST_PHOTO_VIEW} from './entrance-symmetry.mjs';
import {REDESMERE_GARDEN_VIEW} from './redesmere-garden-photo-detail.mjs';
import {EAST_FORWARD_END_PHOTO_VIEW} from './east-forward-end-photo-detail.mjs';
import {WEST_FORWARD_END_PHOTO_VIEW} from './west-forward-end-photo-detail.mjs';
import {WEST_LAWN_PHOTO_VIEW} from './west-lawn-photo-detail.mjs';
import {ENTRANCE_WEST_PHOTO_VIEW} from './entrance-west-photo-detail.mjs';
import {FRONT_CORNER_VIEWS} from './front-inside-corners.mjs';
import {CENTRAL_BACK_VIEWS} from './central-back.mjs';
import {FRONT_LAWN_TREE_VIEW} from './front-lawn-trees.mjs';
const canvas=document.getElementById('game'),hint=document.getElementById('lookHint'),look=document.getElementById('look');
try{
  const renderer=new THREE.WebGLRenderer({canvas,antialias:true});
  renderer.setPixelRatio(Math.min(devicePixelRatio,1.5));renderer.setSize(innerWidth,innerHeight);
  renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.25;
  renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;
  const exterior=createEscapeExterior(THREE,innerWidth/innerHeight);
  canvas.addEventListener('webglcontextrestored',exterior.invalidateShadows);
  exterior.camera.near=.1;exterior.camera.updateProjectionMatrix();
  const layouts=createAerialLayouts(THREE,exterior);
  const timeline=prepareEstateTimeline(THREE,exterior,layouts);
  // Road-name sprites are map overlays; keep them out of the walking view.
  layouts.roads.traverse(object=>{if(object.isSprite)object.visible=false;});
  const obstacles=exteriorObstacles(THREE,exterior.model);
  const walker=createWalker(exterior.camera,obstacles);
  function refreshObstacles(){walker.setObstacles(exteriorObstacles(THREE,exterior.model));}
  bindTimelineControls(timeline,document.getElementById('layoutControls'),refreshObstacles);
  bindTreeToggle(exterior,document,refreshObstacles);
  const view=resolveLocationView(new URLSearchParams(location.search).get('view'));
  if(LOCATION_WALKS[view])walker.setView(LOCATION_WALKS[view]);
  if(CHURCH_VIEWS[view])walker.setView(CHURCH_VIEWS['church-ground']);
  if(CENTRAL_BACK_VIEWS[view])walker.setView(CENTRAL_BACK_VIEWS['central-back-photo']);
  if(view==='front-lawn-trees')walker.setView(FRONT_LAWN_TREE_VIEW);
  if(FRONT_CORNER_VIEWS[view])walker.setView(FRONT_CORNER_VIEWS[view==='front-corners'?'front-corner-2':view]);
  if(view==='front')walker.setView({position:[0,1.8,40],target:[0,9,19.8]});
  if(view==='tower'||WATER_TOWER_VIEWS[view])walker.setView(WATER_TOWER_VIEWS[view==='tower'?'tower-2':view]);
  if(TOWER_BUILDING_VIEWS[view]){
    const shot=TOWER_BUILDING_VIEWS[view.startsWith('pharmacy')?'pharmacy-photo':view==='tower-twin-gables'||view==='tower-twin-gables-site'?'tower-twin-gables':'tower-buildings-3'];
    walker.setView({...shot,position:[shot.position[0],1.8,shot.position[2]]});
  }
  const chimneyView=REDESMERE_CHIMNEY_VIEWS[new URLSearchParams(location.search).get('view')];
  if(chimneyView)walker.setView(chimneyView);
  if(view==='redesmere-passage')walker.setView(REDESMERE_PASSAGE_VIEW);
  if(view==='east-photo')walker.setView(EAST_PHOTO_VIEW);
  if(view==='courtyard-photo')walker.setView(COURTYARD_PHOTO_VIEW);
  if(view==='west-front-photo')walker.setView(WEST_FRONT_PHOTO_VIEW);
  if(view==='west-court-photo')walker.setView(WEST_COURT_PHOTO_VIEW);
  if(view==='inner-court-photo')walker.setView(INNER_COURT_PHOTO_VIEW);
  if(view==='rear-court-photo')walker.setView(REAR_COURT_PHOTO_VIEW);
  if(view==='inner-east-photo')walker.setView(innerEastPhotoView(exterior.camera.aspect));
  if(view==='central-court-photo')walker.setView(centralCourtPhotoView(exterior.camera.aspect));
  if(view==='west-wing-side')walker.setView(WEST_WING_SIDE_VIEW);
  if(view==='west-wing-end')walker.setView(WEST_WING_END_VIEW);
  if(view==='redesmere-photo')walker.setView(REDESMERE_PHOTO_VIEW);
  if(view==='entrance-west-photo')walker.setView(ENTRANCE_WEST_PHOTO_VIEW);
  if(view==='west-lawn-photo')walker.setView(WEST_LAWN_PHOTO_VIEW);
  if(view==='east-lawn-photo')walker.setView(EAST_LAWN_PHOTO_VIEW);
  if(view==='entrance-east-photo')walker.setView(ENTRANCE_EAST_PHOTO_VIEW);
  if(view==='redesmere-garden-photo')walker.setView(REDESMERE_GARDEN_VIEW);
  if(view==='east-forward-end-photo')walker.setView(EAST_FORWARD_END_PHOTO_VIEW);
  if(view==='west-forward-end-photo')walker.setView(WEST_FORWARD_END_PHOTO_VIEW);
  if(view==='front-steps')walker.setView({...FRONT_STEPS_VIEW,position:[6,1.8,34]});
  if(view==='front-wall')walker.setView({...FRONT_WALL_VIEW,position:[0,1.8,36],target:[-12,.8,49]});
  const annexeView=(new URLSearchParams(location.search).get('view')??'').replace(/^new-hospital/,'annexe');
  if(ANNEXE_VIEWS[annexeView])walker.setView(ANNEXE_WARD_WALKS[annexeView]??ANNEXE_VIEWS[['annexe','annexe-plan','annexe-site'].includes(annexeView)?'annexe-ground':annexeView]);
  const churtonView=new URLSearchParams(location.search).get('view');
  if(ESTATES_VIEWS[churtonView])walker.setView(ESTATES_VIEWS['estates-photo']);
  if(OUTHOUSE_VIEWS[churtonView])walker.setView(OUTHOUSE_VIEWS[/^outhouse-[123]$/.test(churtonView)?churtonView:'outhouse-3']);
  if(GREENHOUSE_VIEWS[churtonView])walker.setView(GREENHOUSE_VIEWS['greenhouses-photo']);
  if(GARAGE_MORTUARY_VIEWS[churtonView])walker.setView(GARAGE_MORTUARY_VIEWS[churtonView.startsWith('mortuary')?'mortuary-ground':churtonView==='garages-2'?'garages-2':'garages-1']);
  if(LAUNDRY_VIEWS[churtonView])walker.setView(LAUNDRY_VIEWS['laundry-photo']);
  if(UPTON_VIEWS[churtonView])walker.setView(UPTON_VIEWS['upton-ground']);
  if(FARNDON_VIEWS[churtonView])walker.setView(FARNDON_VIEWS['farndon-2']);
  if(WITBY_VIEWS[churtonView])walker.setView(WITBY_VIEWS['witby-ground']);
  if(GRAFTON_EDGE_VIEWS[churtonView])walker.setView(GRAFTON_EDGE_VIEWS['grafton-edge-ground']);
  if(HALE_WARD_VIEWS[churtonView])walker.setView(HALE_WARD_VIEWS[churtonView.startsWith('hale-corner-photo-')?churtonView:'hale-daresbury-huxley-dunham-ground']);
  if(IRBY_ASHLEY_VIEWS[churtonView])walker.setView(IRBY_ASHLEY_VIEWS[churtonView==='irby-ashley-3'?churtonView:'irby-ashley-1']);
  if(MAIN_ADMIN_VIEWS[churtonView]){
    const shot=MAIN_ADMIN_VIEWS[churtonView==='main-admin'||churtonView==='main-admin-plan'?'main-admin-4':churtonView];
    walker.setView(churtonView.startsWith('irby-corridor')?IRBY_CORRIDOR_WALK:churtonView.startsWith('ward-corridors')?WARD_CORRIDOR_WALK:churtonView.startsWith('farndon-corridor')?FARNDON_CORRIDOR_WALK:churtonView==='main-admin-corridor'?{...shot,position:[136,1.8,28],target:[128,2.1,13]}:shot);
  }
  if(CHURTON_VIEWS[churtonView])walker.setView(CHURTON_VIEWS[churtonView==='churton'||churtonView==='churton-plan'?'churton-4':churtonView]);
  const input=bindExploreInput(walker,{canvas,hint,look,touchControls:document.getElementById('walkTouch')});
  window.addEventListener('resize',()=>{renderer.setSize(innerWidth,innerHeight);exterior.camera.aspect=innerWidth/innerHeight;if(view==='inner-east-photo')exterior.camera.fov=innerEastPhotoView(exterior.camera.aspect).fov;if(view==='central-court-photo')exterior.camera.fov=centralCourtPhotoView(exterior.camera.aspect).fov;exterior.camera.updateProjectionMatrix();});
  const lighting=createDayNight(THREE,exterior,renderer,{walking:true});bindDayNight(lighting);
  const clock=new THREE.Clock();
  renderer.setAnimationLoop(()=>{const dt=clock.getDelta();if(input.active&&!document.hidden)walker.update(dt);lighting.update();renderer.render(exterior.scene,exterior.camera);});
  loadEscapeFrontage(THREE,exterior).catch(error=>console.warn('Frontage photo unavailable',error));
}catch(error){console.error(error);hint.textContent='The grounds could not load. Reload the page to try again.';look.disabled=false;look.textContent='RELOAD ↗';look.onclick=()=>location.reload();}
